#!/usr/bin/env python3
# Some portions generated by Codex. Inclusive sampled methods, not call counts or wall-time.
import json,pathlib,collections,sys
root=pathlib.Path(sys.argv[1]);out={}
for p in sorted(root.glob('*.samples.json')):
 c=collections.Counter()
 for e in json.loads(p.read_text())['recording']['events']:
  v=e['values'];t=v.get('sampledThread') or v.get('eventThread') or {}
  if t.get('javaName')!='main':continue
  names={((f.get('method') or {}).get('type',{}).get('name','?')+'.'+(f.get('method') or {}).get('name','?')).replace('/','.') for f in (v.get('stackTrace') or {}).get('frames',[])}
  c.update(n for n in names if n.startswith('java.lang.ThreadLocal'))
 out[p.stem]=dict(c)
print(json.dumps(out,indent=2))
